/**
 * Asset manifest of the demo (spec 06 F8.1): content refers to ids, the manifest maps them to URLs,
 * kinds, atlas layouts, format variants and sizes. Media is generated by tools/media/gen-demo-media.py.
 */
import type { ManifestEntry, MediaManifest } from "@adventure-engine/content";

const FILES: Readonly<Record<string, string>> = {
  "bg.workroom": "bg-workroom.svg",
  "fg.workroom": "fg-workroom.svg",
  "bg.yard": "bg-yard.svg",
  tove: "tove.svg",
  crow: "crow.svg",
  "clock.stopped": "clock-stopped.svg",
  "clock.running": "clock-running.svg",
  oilcan: "oilcan.svg",
  feather: "feather.svg",
  "icon.oilcan": "icon-oilcan.svg",
  "icon.feather": "icon-feather.svg",
  "icon.oiled_feather": "icon-oiled-feather.svg",
  "img.story1": "story-1.svg",
  "img.story2": "story-2.svg",
  "img.finale": "finale.svg",
};

const ATLASES: Readonly<Record<string, { file: string; frameWidth: number; frameHeight: number; frames: number }>> = {
  "atlas.tove": { file: "tove-atlas.svg", frameWidth: 60, frameHeight: 170, frames: 12 },
  "atlas.crow": { file: "crow-atlas.svg", frameWidth: 80, frameHeight: 90, frames: 4 },
  "atlas.clock": { file: "clock-atlas.svg", frameWidth: 100, frameHeight: 300, frames: 6 },
};

const SOUNDS: Readonly<Record<string, { file: string; bytes: number }>> = {
  "snd.pickup": { file: "pickup.wav", bytes: 2249 },
  "snd.hum": { file: "hum.wav", bytes: 22094 },
  "snd.theme": { file: "theme.wav", bytes: 44144 },
};

export function demoManifest(base: string): MediaManifest {
  const out: Record<string, ManifestEntry> = {};
  for (const [id, file] of Object.entries(FILES)) out[id] = { kind: "image", url: `${base}assets/${file}` };
  for (const [id, a] of Object.entries(ATLASES)) {
    out[id] = { kind: "atlas", url: `${base}assets/${a.file}`, atlas: { frameWidth: a.frameWidth, frameHeight: a.frameHeight, frames: a.frames } };
  }
  // WAV is playable in every target browser; the format list allows better codecs to be added first.
  for (const [id, s] of Object.entries(SOUNDS)) out[id] = { kind: "audio", formats: [{ url: `${base}media/${s.file}`, type: "audio/wav", bytes: s.bytes }], bytes: s.bytes };
  return out;
}
